/**
 * Tex's one config is what the gateway runs (Dev2, 2026-11-13: "I want the config generated by the lab to become the
 * production code, and to be the only source of truth"). Each model-calling step asks `texConfig.js` for its model,
 * effort and time limit, and the texting setup's models come from the config, never from the setup note.
 *
 * Sabotage record (temporary local edits, reverted, 2026-11-13):
 *   replyJudge.js back to its own `effort: "low"`             "each judge asks the config how hard to think" fails
 *   texSetupFront() giving main effort high                   "a setup note with no models runs on the config's" fails
 *   the router on in texConfig.json                           "a step the code cannot run is never on" fails
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { TEX_CONFIG, texEffort, texModel, texSetupFront, texStep, texTimeoutMs } from "../src/agent/texConfig.js";
import { parseSetup } from "../src/agent/production.js";
import { REVIEW_MODEL, REVIEW_TIMEOUT_MS } from "../src/agent/replyJudge.js";
import { MAIL_CHECKER_MODEL } from "../src/agent/mailChecker.js";
import { CARD_CHECK_MODEL } from "../src/agent/cardCheck.js";
import { HANDBACK_JUDGE_MODEL } from "../src/agent/handbackJudge.js";
import { SELF_REVIEW_MODEL } from "../src/agent/selfReview.js";
import { THREADS_MODEL, THREADS_TIMEOUT_MS } from "../src/agent/conversationThreads.js";
import { ADVISOR_TIMEOUT_MS } from "../src/agent/advisor.js";

const FINGERPRINT_SETUP = new URL("../bench/fingerprint/setups/texting-assistant/production.md", import.meta.url);
const src = (file) => readFileSync(new URL(`../src/agent/${file}`, import.meta.url), "utf8");

test("every step's model is in the config's table, and every wire joins two steps", () => {
  const ids = new Set(TEX_CONFIG.nodes.map((n) => n.id));
  for (const n of TEX_CONFIG.nodes) if (n.model !== "code") assert.equal(typeof TEX_CONFIG.models[n.model], "string", n.id);
  for (const e of TEX_CONFIG.edges) assert.ok(ids.has(e.from) && ids.has(e.to), `${e.from} -> ${e.to}`);
  assert.equal(ids.size, TEX_CONFIG.nodes.length, "step ids are unique");
});

test("each judge's model and time limit is the config's", () => {
  assert.deepEqual(
    [REVIEW_MODEL, MAIL_CHECKER_MODEL, CARD_CHECK_MODEL, HANDBACK_JUDGE_MODEL, SELF_REVIEW_MODEL, THREADS_MODEL],
    ["reviewer", "mail", "card", "handback", "selfreview", "classifier"].map(texModel),
  );
  assert.deepEqual([REVIEW_TIMEOUT_MS, THREADS_TIMEOUT_MS, ADVISOR_TIMEOUT_MS.chat], [texTimeoutMs("reviewer"), texTimeoutMs("classifier"), texTimeoutMs("advisor")]);
});

test("each judge asks the config how hard to think, and no model file keeps an effort or model id of its own", () => {
  for (const [file, id] of [["replyJudge.js", "reviewer"], ["mailChecker.js", "mail"], ["cardCheck.js", "card"], ["handbackJudge.js", "handback"], ["selfReview.js", "selfreview"], ["conversationThreads.js", "classifier"]]) {
    const text = src(file);
    assert.match(text, new RegExp(`texEffort\\("${id}"\\)`), file);
    assert.doesNotMatch(text, /effort: "(?:off|low|medium|high|xhigh|max)"/, file);
    assert.doesNotMatch(text, /= "anthropic\/claude-[a-z0-9.-]+"/, file);
  }
  assert.deepEqual(texEffort("classifier"), { effort: "low", thinking: "off" });
  assert.deepEqual(texEffort("reviewer"), { effort: texStep("reviewer").effort });
});

test("a setup note with no models runs on the config's, exactly as the same note naming the config's models", async () => {
  const bare = readFileSync(FINGERPRINT_SETUP, "utf8").replace(/^modules:\n(?: {2}.*\n)+/m, "");
  assert.doesNotMatch(bare, /^(?:models|reply_judge|plan_big_asks):/m, "the fingerprint copy names no models, as production's note names none");
  const front = texSetupFront();
  const lines = Object.entries(front.models).map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`).join("\n");
  const named = await parseSetup(bare.replace(/^---\n/, `---\nmodels:\n${lines}\nreply_judge: ${front.reply_judge}\n`));
  const fromConfig = await parseSetup(bare);
  assert.ok(named && fromConfig, "both parse");
  const strip = ({ version, ownModels, ...rest }) => rest;
  assert.deepEqual(strip(fromConfig), strip(named), "the config's models are what naming them would give");
  assert.deepEqual([named.ownModels, fromConfig.ownModels], [true, false]);
  assert.equal(fromConfig.model, texModel("fd"));
  assert.equal(fromConfig.advisor, texStep("advisor").on ? texModel("advisor") : null);
  assert.equal(fromConfig.fallback, texStep("fallback").on ? texModel("fallback") : null);
  assert.equal(fromConfig.efforts[texModel("fd")], texStep("fd").effort);
  assert.equal(fromConfig.planBigAsks, texStep("planner").on);
  assert.equal(fromConfig.replyJudge !== null, texStep("reviewer").on);

  // A reviewer line left in a note with no models is the config's to answer, and is named.
  const stale = await parseSetup(bare.replace(/^---\n/, "---\nreply_judge: off\n"));
  assert.equal(stale.replyJudge !== null, texStep("reviewer").on);
  assert.deepEqual([stale.ownModels, stale.ignored], [false, ["reply_judge"]]);
  // A bench variant keeps the models it was written to compare, and says so.
  const variant = await parseSetup(bare.replace(/^---\n/, "---\nmodels:\n  main: anthropic/claude-sonnet-5-5\n"));
  assert.deepEqual([variant.model, variant.ownModels], ["anthropic/claude-sonnet-5-5", true]);
});

test("the advisor's four roles share one model and effort in code, so the config gives them one", () => {
  for (const id of ["jobcheck", "mailadv", "planner"]) {
    assert.deepEqual([id, texModel(id), texStep(id).effort], [id, texModel("advisor"), texStep("advisor").effort]);
  }
  assert.deepEqual([texModel("job"), texStep("job").model], [texModel("fd"), texStep("fd").model], "a job runs on main");
});

test("a step the code cannot run is never on: the router needs a thinking model the config does not name yet", () => {
  assert.equal(texStep("router").on, false);
});

test("both send-backs reach the front door: the reviewer's after an action, and the answer checks' on any draft (sendBack.js)", () => {
  const loops = TEX_CONFIG.edges.filter((e) => e.mode === "loop" && e.to === "fd").map((e) => [e.from, e.when.join()]);
  assert.deepEqual(loops, [["reviewer", "action"], ["checks", "*"]]);
});
